import {Button, FormControl, TextInput} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useState} from 'react'

import styles from './ActionsCustomImagesRetentionPolicy.module.css'

export interface ActionsCustomImagesRetentionPolicyProps {
  imageVersionsPerImageLimit: number
  imageVersionsMaxAgeLimit: number
  imageVersionsUnusedAgeLimit: number
  imageVersionsPerImageLimitMin: number
  imageVersionsMaxAgeLimitMin: number
  imageVersionsUnusedAgeLimitMin: number
  imageVersionsPerImageLimitMax: number
  imageVersionsMaxAgeLimitMax: number
  imageVersionsUnusedAgeLimitMax: number
  update_custom_image_retention_policy_path: string
  isOrganizationLevel?: boolean
}

interface IActionsCustomImagesRetentionPolicyUpdate {
  imageVersionsPerImageLimit: string
  imageVersionsMaxAgeLimit: string
  imageVersionsUnusedAgeLimit: string
}

interface ValidationState {
  imageVersions: {isValid: boolean; message: string}
  unusedAge: {isValid: boolean; message: string}
  age: {isValid: boolean; message: string}
}

export function ActionsCustomImagesRetentionPolicy(props: ActionsCustomImagesRetentionPolicyProps) {
  const [imageVersionsPerImageLimit, setImageVersionsPerImageLimit] = useState<string>(
    props.imageVersionsPerImageLimit.toString(),
  )
  const [imageVersionsMaxAgeLimit, setImageVersionsMaxAgeLimit] = useState<string>(
    props.imageVersionsMaxAgeLimit.toString(),
  )
  const [imageVersionsUnusedAgeLimit, setImageVersionsUnusedAgeLimit] = useState<string>(
    props.imageVersionsUnusedAgeLimit.toString(),
  )
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [validation, setValidation] = useState<ValidationState>({
    imageVersions: {isValid: true, message: ''},
    unusedAge: {isValid: true, message: ''},
    age: {isValid: true, message: ''},
  })

  const validateField = (value: string, minValue: number, maxValue: number): {isValid: boolean; message: string} => {
    if (!value.trim()) {
      return {isValid: false, message: 'This field is required'}
    }

    const numValue = parseInt(value, 10)
    if (isNaN(numValue) || numValue < minValue) {
      return {isValid: false, message: `Must be ${minValue} or more`}
    }

    if (numValue > maxValue) {
      return {isValid: false, message: `Must be ${maxValue} or less`}
    }

    return {isValid: true, message: ''}
  }

  const validateImageVersions = (value: string) => {
    return validateField(value, props.imageVersionsPerImageLimitMin, props.imageVersionsPerImageLimitMax)
  }

  const validateUnusedAge = (value: string) => {
    return validateField(value, props.imageVersionsUnusedAgeLimitMin, props.imageVersionsUnusedAgeLimitMax)
  }

  const validateAge = (value: string) => {
    return validateField(value, props.imageVersionsMaxAgeLimitMin, props.imageVersionsMaxAgeLimitMax)
  }

  const validateAllFields = (): boolean => {
    const imageVersionsResult = validateImageVersions(imageVersionsPerImageLimit)
    const unusedAgeResult = validateUnusedAge(imageVersionsUnusedAgeLimit)
    const ageResult = validateAge(imageVersionsMaxAgeLimit)

    setValidation({
      imageVersions: imageVersionsResult,
      unusedAge: unusedAgeResult,
      age: ageResult,
    })

    return imageVersionsResult.isValid && unusedAgeResult.isValid && ageResult.isValid
  }

  const isFormValid = validation.imageVersions.isValid && validation.unusedAge.isValid && validation.age.isValid

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setSuccessMessage(null)

    if (!validateAllFields()) {
      return
    }

    setIsSubmitting(true)

    const updateData: IActionsCustomImagesRetentionPolicyUpdate = {
      imageVersionsPerImageLimit,
      imageVersionsMaxAgeLimit,
      imageVersionsUnusedAgeLimit,
    }

    try {
      const response = await reactFetchJSON(props.update_custom_image_retention_policy_path, {
        method: 'PUT',
        body: updateData,
      })

      if (response.ok) {
        setError(null)
        setSuccessMessage('Custom image retention settings updated successfully!')
      } else {
        setError('Failed to update retention policy. Please try again.')
      }
    } catch (err) {
      setError(`An error occurred while updating the policy. Please try again. ${err}`)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} data-test-selector="custom-images-retention-policy-form">
      <div>
        <p>Choose the default settings for custom image retention in this enterprise.</p>
      </div>

      <FormControl className={styles.formControl}>
        <FormControl.Label>Maximum versions per image</FormControl.Label>
        <div className={styles.inputRow}>
          <TextInput
            type="number"
            value={imageVersionsPerImageLimit}
            onChange={e => {
              setImageVersionsPerImageLimit(e.target.value)
              const result = validateImageVersions(e.target.value)
              setValidation(prev => ({...prev, imageVersions: result}))
            }}
            className={styles.inputWidth130}
            validationStatus={validation.imageVersions.isValid ? undefined : 'error'}
          />
          <span>versions</span>
        </div>
        {!validation.imageVersions.isValid && (
          <FormControl.Validation variant="error">{validation.imageVersions.message}</FormControl.Validation>
        )}
        <FormControl.Caption>
          {props.isOrganizationLevel ? (
            <span>
              Your enterprise has set a maximum limit of <strong>{props.imageVersionsPerImageLimitMax}</strong> versions
              per image.
            </span>
          ) : (
            <span>
              Limits how many versions to store for every image. When this limit is exceeded, the oldest unused image
              version is deleted.
            </span>
          )}
        </FormControl.Caption>
      </FormControl>

      <FormControl className={styles.formControl}>
        <FormControl.Label>Unused version retention</FormControl.Label>
        <div className={styles.inputRow}>
          <TextInput
            type="number"
            value={imageVersionsUnusedAgeLimit}
            onChange={e => {
              setImageVersionsUnusedAgeLimit(e.target.value)
              const result = validateUnusedAge(e.target.value)
              setValidation(prev => ({...prev, unusedAge: result}))
            }}
            className={styles.inputWidth105}
            validationStatus={validation.unusedAge.isValid ? undefined : 'error'}
          />
          <span>days</span>
        </div>
        {!validation.unusedAge.isValid && (
          <FormControl.Validation variant="error">{validation.unusedAge.message}</FormControl.Validation>
        )}
        <FormControl.Caption>
          {props.isOrganizationLevel ? (
            <span>
              Your enterprise has set a maximum limit of <strong>{props.imageVersionsUnusedAgeLimitMax}</strong> days
              for unused version retention.
            </span>
          ) : (
            <span>
              Sets how long unused image versions are retained. When this policy is enforced, image versions not used
              for more than the specified number of days are deleted.
            </span>
          )}
        </FormControl.Caption>
      </FormControl>

      <FormControl className={styles.formControl}>
        <FormControl.Label>Maximum version age</FormControl.Label>
        <div className={styles.inputRow}>
          <TextInput
            type="number"
            value={imageVersionsMaxAgeLimit}
            onChange={e => {
              setImageVersionsMaxAgeLimit(e.target.value)
              const result = validateAge(e.target.value)
              setValidation(prev => ({...prev, age: result}))
            }}
            className={styles.inputWidth105}
            validationStatus={validation.age.isValid ? undefined : 'error'}
          />
          <span>days</span>
        </div>
        {!validation.age.isValid && (
          <FormControl.Validation variant="error">{validation.age.message}</FormControl.Validation>
        )}
        <FormControl.Caption>
          {props.isOrganizationLevel ? (
            <span>
              Your enterprise has set a maximum limit of <strong>{props.imageVersionsMaxAgeLimitMax}</strong> days for
              maximum version age.
            </span>
          ) : (
            <span>
              Defines the maximum age for an image version. After this period, the image version will be disabled and
              will not be usable by runners.
            </span>
          )}
        </FormControl.Caption>
      </FormControl>

      {successMessage && (
        <div className={styles.messageWrapper}>
          <InlineMessage variant="success">{successMessage}</InlineMessage>
        </div>
      )}

      {error && (
        <div className={styles.messageWrapper}>
          <InlineMessage variant="critical">{error}</InlineMessage>
        </div>
      )}

      <Button type="submit" disabled={!isFormValid || isSubmitting} variant="default">
        {isSubmitting ? 'Saving...' : 'Save'}
      </Button>
    </form>
  )
}
